<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Delete, Edit, Plus, Search } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../services/api'
import type { Product, Supplier } from '../types/domain'

const rows = ref<Supplier[]>([]); const products = ref<Product[]>([]); const keyword = ref(''); const visible = ref(false); const editingId = ref<string | null>(null)
const form = reactive({ name: '', contact: '', position: '', whatsapp: '', phone: '', email: '', address: '', note: '', productIds: [] as string[] })
const reset = () => Object.assign(form, { name: '', contact: '', position: '', whatsapp: '', phone: '', email: '', address: '', note: '', productIds: [] })
async function load() { [rows.value, products.value] = await Promise.all([api.suppliers.list(), api.products.list()]) }
function edit(row: Supplier) { editingId.value = row.id; Object.assign(form, { name: row.name, contact: row.contact, position: row.position, whatsapp: row.whatsapp, phone: row.phone, email: row.email, address: row.address, note: row.note, productIds: [...row.productIds] }); visible.value = true }
function create() { editingId.value = null; reset(); visible.value = true }
async function save() { if (!form.name || !form.contact) return ElMessage.warning('供应商名称和联系人不能为空'); try { if (editingId.value) await api.suppliers.update(editingId.value, form); else await api.suppliers.create(form); await load(); visible.value = false; ElMessage.success('供应商已保存') } catch (error) { ElMessage.error((error as Error).message) } }
async function remove(row: Supplier) { try { await ElMessageBox.confirm(`确定删除“${row.name}”吗？`, '删除确认', { type: 'warning' }); await api.suppliers.remove(row.id); await load(); ElMessage.success('已删除') } catch (error) { if ((error as Error).message !== 'cancel') ElMessage.error((error as Error).message) } }
function productNames(ids: string[]) { return ids.map((id) => products.value.find((item) => item.id === id)?.name ?? '').filter(Boolean).join('、') || '—' }
onMounted(() => load().catch((error) => ElMessage.error(error.message)))
</script>
<template><div class="page-view"><div class="page-heading"><div><h1>供应商库</h1><p>维护供应商档案与联系方式，可关联产品库产品</p></div><el-button type="primary" :icon="Plus" @click="create">新增供应商</el-button></div><el-card class="content-card" shadow="never"><div class="filter-bar"><el-input v-model="keyword" clearable :prefix-icon="Search" placeholder="搜索供应商名称、联系人或邮箱" /></div><el-table :data="rows.filter((row) => `${row.name} ${row.contact} ${row.email}`.toLowerCase().includes(keyword.toLowerCase()))"><el-table-column prop="name" label="供应商名称" min-width="180"/><el-table-column prop="contact" label="联系人" width="110"/><el-table-column prop="position" label="职位" width="120"/><el-table-column prop="whatsapp" label="联系方式" width="160"/><el-table-column prop="phone" label="联系号码" width="150"/><el-table-column prop="email" label="邮箱" min-width="200"/><el-table-column label="对应产品" min-width="200"><template #default="{ row }">{{ productNames(row.productIds) }}</template></el-table-column><el-table-column prop="address" label="地址" min-width="160"/><el-table-column prop="note" label="备注" min-width="160"/><el-table-column label="操作" width="150" fixed="right"><template #default="{ row }"><el-button link :icon="Edit" @click="edit(row)">编辑</el-button><el-button link type="danger" :icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" :title="editingId ? '编辑供应商' : '新增供应商'" width="600px"><el-form label-width="90px"><el-form-item label="供应商名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="联系人"><el-input v-model="form.contact"/></el-form-item><el-form-item label="职位"><el-input v-model="form.position"/></el-form-item><el-form-item label="联系方式"><el-input v-model="form.whatsapp" placeholder="WhatsApp / 微信等"/></el-form-item><el-form-item label="联系号码"><el-input v-model="form.phone" placeholder="手机 / 座机"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="地址"><el-input v-model="form.address"/></el-form-item><el-form-item label="对应产品"><el-select v-model="form.productIds" multiple class="full-width" placeholder="选择该供应商供货的产品"><el-option v-for="item in products" :key="item.id" :label="`${item.name}（${item.sku}）`" :value="item.id"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="form.note" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
